/* Views, part 2: Orders, Copy trade, Sniper, Signals, Wallets, Portfolio, Automation hub, secondary pages. */
const failBox=(what,retry)=>`<div class="panel">${notice('error',`Could not load ${what}`,'The request failed, so what you see may be out of date. Nothing was changed.')}${retry?`<button class="btn" style="margin-top:10px" data-retry>Try again</button>`:''}</div>`;
const KIND={limit_buy:'Limit buy',limit_sell:'Limit sell',take_profit:'Take profit',stop_loss:'Stop loss',trailing_stop:'Trailing stop'};
const tokOpts=()=>S.ov.tokens.map(t=>`<option value="${t.address}">${esc(t.sym)}</option>`).join('');
const wOpts=sel=>S.ov.wallets.map(w=>`<option value="${w.id}" ${w.id===sel?'selected':''}>${esc(w.name)} · ${NET()}</option>`).join('');
const tmin=m=>m;

/* ---------- Orders ---------- */
V.orders={title:'Orders',needsData:true,
html(){return practiceNote()+head('Orders and automation','Every rule that can trade for you, in one table. Click a row to see why it did, or did not, act.',`<button class="btn primary" id="newr">New rule</button>`)+
  `<div class="stack"><div class="panel flush"><div class="tw" id="ot">${skeleton(3)}</div></div>${this.twapHtml()}${this.bulkHtml()}
  <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr))"><div class="panel"><h2>Balance reservations</h2><p class="muted" style="margin:4px 0 10px">A balance can back only one rule. If you try to reuse it, the second rule is refused, never silently split.</p><div id="rs"></div></div>
  <div class="panel stack"><h2>${isLive()?'Market':'Practice controls'}</h2>${isLive()?'<p class="muted">Rules check the forked pool on every new block.</p>':'<p class="muted">Move the simulated MEME market to watch rules react.</p><div class="row"><button class="btn sm" data-m="up">Push MEME price up</button><button class="btn sm" data-m="down">Drop MEME price</button></div>'}<div class="row sb"><span class="muted">${isLive()?'USDC price (ETH per USDC)':'MEME price'}</span><b class="num" id="cp"></b></div></div></div></div>`},
realRule(){const host=$('.stack',$('#view'));if(!host||$('#rcp')||!S.realInfo?.enabled||!(S.real||[]).length)return;
  const toks=[...S.real].filter(t=>t.price>0).sort((a,b)=>(b.liq||0)-(a.liq||0)).slice(0,120),ok=t=>t.pad===null&&(t.chain==='solana'?/raydium/i.test(t.venue):/uniswap v2|pancakeswap v2/i.test(t.venue));
  const p=document.createElement('div');p.className='panel stack';p.id='rcp';p.innerHTML=`<h2>Check a rule against a real token</h2><p class="muted">See where a real token's price is now, how far it is from your trigger, and whether this engine could act on it. Preview only: nothing is placed, and the price is from DexScreener (third party, can be wrong).</p>
  <div class="row"><div style="min-width:180px"><label for="rct">Token</label><select id="rct">${toks.map((t,i)=>`<option value="${i}">${esc(t.sym)} · ${esc((CHAINS[t.chain]||{}).name||t.chain)}</option>`).join('')}</select></div><div><label for="rck">Rule</label><select id="rck"><option value="tp">Take profit</option><option value="sl">Stop loss</option><option value="lb">Limit buy</option></select></div><div><label for="rcv">Trigger price (USD)</label><input id="rcv" inputmode="decimal"></div></div><div id="rcr" aria-live="polite"></div>`;host.appendChild(p);
  const cur=()=>toks[Number($('#rct').value)],def=()=>{const t=cur(),k=$('#rck').value;$('#rcv').value=price(t.price*(k==='tp'?1.3:k==='sl'?.8:.85))},
  run=()=>{const t=cur(),k=$('#rck').value,v=Number($('#rcv').value.replace(/,/g,''));const r=$('#rcr');if(!(v>0)){r.innerHTML=notice('warn','Enter a trigger price','Use a number greater than zero.');if(!r.id)r.id='rcr';invalid($('#rcv'),r);return}
    const d=(v/t.price-1)*100,hit=k==='tp'?t.price>=v:t.price<=v,wrongSide=(k==='tp'&&v<=t.price)||(k!=='tp'&&v>=t.price);const why=[];
    if(!ok(t))why.push(t.pad?`${t.pad==='pump-fun'?'Pump.fun':'this launchpad'} curves cannot be traded by this engine yet`:`${t.venue} is not a venue this engine trades`);
    if((t.liq||0)<5000)why.push(`pool liquidity $${compact(t.liq||0)} is under the $5,000 floor, so the rule would refuse to fire`);
    r.innerHTML=notice(hit?'warn':'plain',hit?'Would trigger right now':'Not triggered',`<div>${esc(t.sym)} is $${price(t.price)} now. Your ${k==='tp'?'take-profit':k==='sl'?'stop-loss':'limit-buy'} trigger of $${price(v)} is ${Math.abs(d).toFixed(1)}% ${d>=0?'above':'below'} the current price.</div>`+(wrongSide&&!hit?`<div class="faint">A ${k==='tp'?'take profit':k==='sl'?'stop loss':'limit buy'} normally sits ${k==='tp'?'above':'below'} the current price.</div>`:''))+
      notice(why.length?'warn':'ok',why.length?'This engine could not act on it':'This engine could act on it',why.length?`<div>${why.map(esc).join('; ')}.</div>`:`<div>${esc(t.venue)} is a supported venue and the pool is deep enough. A real rule would also need a fresh pool quote and an output within the allowed deviation when it fires.</div>`)};
  $('#rct').onchange=()=>{def();run()};$('#rck').onchange=()=>{def();run()};$('#rcv').oninput=run;def();run()},
mount(){$('#newr').onclick=()=>this.newRule();const nb=$('#newbk');if(nb)nb.onclick=()=>this.newBulk();const bp=$('#bkp');if(bp)bp.addEventListener('click',e=>{const r=e.target.closest('tr[data-bk]');if(r)this.bulkLog(r.dataset.bk)});const nt=$('#newtw');if(nt)nt.onclick=()=>this.newTwap();const tp=$('#twp');if(tp)tp.addEventListener('click',async e=>{const c=e.target.closest('[data-tc]');if(c){e.stopPropagation();modal({title:'Cancel this TWAP order?',body:'<p class="muted">Slices not yet sent are skipped. A slice already sent will still finish.</p>',actions:[{label:'Keep it',cls:'ghost'},{label:'Cancel order',cls:'danger',fn:async()=>{await act('/api/twap/cancel',{id:c.dataset.tc});this.drawTwap()}}]});return}const f=e.target.closest('[data-tf]');if(f){await act('/api/twap/forward',{seconds:Number(f.dataset.tf)});this.drawTwap();return}const r=e.target.closest('tr[data-tw]');if(r)this.twapLog(r.dataset.tw)});setTimeout(()=>this.realRule(),400);$('.stack',$('#view')).addEventListener('click',async e=>{const m=e.target.closest('[data-m]');if(m){await act('/api/market-move',{direction:m.dataset.m});this.tick()}const c=e.target.closest('[data-c]');if(c){e.stopPropagation();modal({title:'Cancel this rule?',body:'<p class="muted">The balance it reserved becomes free again. Linked take-profit and stop-loss pairs are cancelled together.</p>',actions:[{label:'Keep rule',cls:'ghost'},{label:'Cancel rule',cls:'danger',fn:async()=>{await api('/api/orders/cancel',{id:c.dataset.c});this.tick()}}]});return}
  const r=e.target.closest('tr[data-id]');if(r)this.log(r.dataset.id)});this.tick()},
async tick(){const ot=$('#ot');if(!ot)return;this.drawTwap();this.drawBulk();let ord,cp;try{[ord,cp]=await Promise.all([api('/api/orders'),isLive()?null:api('/api/copy')])}catch{ot.innerHTML=failBox('orders');return}
  this.ord=ord;const pt=isLive()?S.ov.tokens[0]:S.ov.tokens.find(t=>t.address==='0xMEME');$('#cp').textContent=pt?price(pt.price)+' '+QSYM():'–';
  const rows=ord.map(o=>({id:o.id,strat:KIND[o.kind]||o.kind,oco:o.oco,tok:o.token,w:walletName(o.walletId),alloc:o.kind==='limit_buy'?fa(o.amount,'native'):fa(o.amount,o.tokenAddr),cond:o.label,chip:orderChip(o),why:o.statusText,ev:o.status==='active'?`Block ${S.ov.block}`:'–',live:o.status==='active'}));
  const cpRow=cp?`<tr class="click" data-id="__copy"><td>Copy trade<div class="faint" style="font-size:12px">follows whale.sim</div></td><td>Any token the leader trades ${chainChip('practice')}</td><td>${esc(walletName(cp.cfg.walletId))}</td><td class="num">${fmt(cp.cfg.maxPerLeader)} SIM cap</td><td>Copies the leader's swaps</td><td>${copyChip(cp)}</td><td class="faint">On each leader trade</td><td><button class="btn sm" disabled title="Manage on the Copy trade page">Manage</button></td></tr>`:'';
  const cpRowOut=cp?cpRow:'';ot.innerHTML=`<table class="tbl-cards"><thead><tr><th>Strategy</th><th>Token / chain</th><th>Wallet</th><th>Allocation</th><th>Condition</th><th>State</th><th>Last evaluation</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr class="click" data-id="${r.id}"><td data-l="Strategy">${r.strat}${r.oco?`<div class="faint" style="font-size:12px">linked pair ${esc(r.oco)}</div>`:''}</td><td data-l="Token">${esc(r.tok)} ${chainChip('practice')}</td><td data-l="Wallet">${esc(r.w)}</td><td data-l="Allocation" class="num">${r.alloc}</td><td data-l="Condition">${esc(r.cond)}</td><td data-l="State">${r.chip}<div class="muted" style="font-size:12px">${esc(r.why)}</div></td><td data-l="Last evaluated" class="faint">${r.ev}</td><td data-l="Actions"><div class="row" style="gap:5px"><button class="btn sm" disabled title="Not available yet: cancel and create a new rule">Edit</button><button class="btn sm" disabled title="Not available yet: cancel the rule instead">Pause</button><button class="btn sm danger" data-c="${r.id}" ${r.live?'':'disabled'}>Cancel</button></div></td></tr>`).join('')}${cpRowOut}</tbody></table>${rows.length?'':`<div class="empty"><b>No price rules yet</b>Rules sell or buy when a price condition is met and the pool can fill it.<br><button class="btn primary" id="newr2">Create a rule</button></div>`}`;
  const n2=$('#newr2');if(n2)n2.onclick=()=>this.newRule();
  const held=[];S.ov.wallets.forEach(w=>{const sells={};ord.filter(o=>o.walletId===w.id&&o.status==='active'&&o.kind!=='limit_buy').forEach(o=>{const k=o.oco||o.id;sells[k]=sells[k]||{tok:o.token,addr:o.tokenAddr,amt:BigInt(o.amount)}});
    const byTok={};Object.values(sells).forEach(s=>{(byTok[s.addr]=byTok[s.addr]||{sym:s.tok,r:0n}).r+=s.amt});
    Object.entries(byTok).forEach(([a,v])=>held.push([w.name,v.sym,balOf(w.id,a),v.r,a]))});
  $('#rs').innerHTML=held.length?`<div class="tw"><table><thead><tr><th>Wallet</th><th>Asset</th><th class="r">Held</th><th class="r">Reserved</th><th class="r">Free</th></tr></thead><tbody>${held.map(h=>`<tr><td>${esc(h[0])}</td><td>${esc(h[1])}</td><td class="r num">${secret(fa(h[2],h[4],{bare:true}))}</td><td class="r num">${secret(fa(h[3],h[4],{bare:true}))}</td><td class="r num">${secret(fa(h[2]-h[3],h[4],{bare:true}))}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty" style="padding:14px"><b>Nothing reserved</b>Active sell rules hold part of your balance here.</div>`},
bulkHtml(){return `<div class="panel stack" id="bkp"><div class="row sb"><div><h2>Multi-wallet orders</h2><p class="muted" style="margin:4px 0 0">Buy or sell the same token from several of your wallets in one request. Each wallet trades on its own with its own limits, one after another. It is not all-or-nothing: if one wallet fails or cannot fund its share, the others still trade and the order shows which.</p></div><div class="row"><button class="btn primary" id="newbk">New multi-wallet order</button></div></div><div class="tw" id="bkt"></div></div>`},
async drawBulk(){const h=$('#bkt');if(!h)return;let t;try{t=await api('/api/bulk')}catch{return}this.bk=t;
  if(!t.length){h.innerHTML='<div class="empty" style="padding:16px"><b>No multi-wallet orders</b>Use "New multi-wallet order" to trade one token from several wallets.</div>';return}
  h.innerHTML=`<table class="tbl-cards"><thead><tr><th>Order</th><th>Wallets</th><th class="r">Spent</th><th class="r">Received</th><th>State</th></tr></thead><tbody>${t.map(o=>{const buy=o.side==='buy',n=o.legs.length;
    return `<tr class="click" data-bk="${o.id}"><td data-l="Order">${buy?'Buy':'Sell'} ${esc(o.token)}<div class="faint" style="font-size:12px">${o.mode==='parallel'?'all wallets at once':'one wallet at a time'}${o.maxImpactBps?`, price impact limit ${o.maxImpactBps/100}%`:''}</div></td>
    <td data-l="Wallets">${o.filled} of ${n} traded<div class="faint" style="font-size:12px">${o.skipped?`${o.skipped} skipped`:''}${o.skipped&&o.failed?', ':''}${o.failed?`${o.failed} failed`:''}${!o.skipped&&!o.failed&&o.open?`${o.open} to go`:''}</div></td>
    <td class="r num" data-l="Spent">${secret(fa(o.spent,buy?'native':o.tokenAddr,{bare:true}))}</td><td class="r num" data-l="Received">${secret(fa(o.received,buy?o.tokenAddr:'native',{bare:true}))}</td><td data-l="State">${esc(o.refused?'Refused: '+o.refused:o.error?'Waiting: '+o.error:o.statusText)}</td></tr>`}).join('')}</tbody></table>`},
bulkLog(id){const o=(this.bk||[]).find(x=>x.id===id);if(!o)return;const buy=o.side==='buy';
  const ST={pending:'Waiting',inflight:'Sent, confirming',filled:'Traded',failed:'Failed',skipped:'Skipped'};
  modal({title:`${buy?'Buy':'Sell'} ${esc(o.token)} · multi-wallet`,drawer:true,body:`<div class="stack">${o.refused?notice('error','Nothing was traded',`<div>${esc(o.refused)}.</div>`):notice(o.done?'plain':'info','What this order is doing',`<div>${esc(o.statusText)}.</div><div class="faint" style="margin-top:4px">${o.filled} of ${o.legs.length} wallets traded. Each wallet is a normal trade checked against that wallet's own limits. The wallets are not traded as one all-or-nothing basket.</div>`)}
  <div class="tw"><table><thead><tr><th>Wallet</th><th class="r">Amount</th><th>State</th><th class="r">Received</th><th>Note</th></tr></thead><tbody>${o.legs.map(l=>`<tr><td>${esc(l.wallet)}</td><td class="r num">${secret(fa(l.amount,buy?'native':o.tokenAddr,{bare:true}))}</td><td>${ST[l.status]||l.status}</td><td class="r num">${l.received==null?'–':secret(fa(l.received,buy?o.tokenAddr:'native',{bare:true}))}</td><td class="faint">${esc(l.reason||'')}</td></tr>`).join('')}</tbody></table></div></div>`})},
newBulk(){const sq=QSYM(),ws=S.ov.wallets;
  modal({title:'New multi-wallet order',body:`<div class="stack"><div class="row"><div><label for="bks">Direction</label><select id="bks"><option value="buy">Buy</option><option value="sell">Sell</option></select></div><div style="flex:1"><label for="bkk">Token</label><select id="bkk">${tokOpts()}</select></div></div>
  <fieldset style="border:0;padding:0;margin:0"><legend class="muted" style="padding:0">Wallets to trade from</legend>${ws.map((w,i)=>`<div class="row" style="gap:8px;align-items:center"><label class="row" style="gap:8px;flex:1"><input type="checkbox" class="bkw" value="${w.id}" ${i<2?'checked':''}> ${esc(w.name)}</label><input class="bkx" data-w="${w.id}" inputmode="numeric" placeholder="amount" aria-label="Amount for ${esc(w.name)}" style="width:130px;display:none"></div>`).join('')}</fieldset>
  <div><label for="bkd">Amounts</label><select id="bkd"><option value="equal">One total, split equally</option><option value="each">Set an amount for each wallet</option></select></div>
  <div id="bkaw"><label for="bka" id="bkal">Total to spend (${sq}), split equally</label><input id="bka" inputmode="numeric" placeholder="e.g. 40000"></div>
  <div class="row"><div><label for="bkm">Wallets trade</label><select id="bkm"><option value="sequential" selected>One after another (recommended)</option><option value="parallel">All at once (later wallets can fail)</option></select></div><div><label for="bki">Stop if the whole amount would move the price more than (%)</label><input id="bki" inputmode="decimal" placeholder="no limit"></div></div>
  <label class="row" style="gap:8px"><input type="checkbox" id="bkf"> Stop the rest if one wallet fails</label><p class="muted" id="bkh"></p><div id="bke"></div></div>`,
  actions:[{label:'Cancel',cls:'ghost'},{label:'Start order',cls:'primary',fn:async()=>{const buy=$('#bks').value==='buy',ids=$$('.bkw').filter(x=>x.checked).map(x=>x.value),unit=buy?'native':$('#bkk').value,each=$('#bkd').value==='each';let raw,amounts;
    if(!ids.length){$('#bke').innerHTML=notice('warn','Pick a wallet','Tick at least one wallet.');invalid($$('.bkw')[0],$('#bke'));return false}
    if(each){amounts={};raw=0n;for(const id of ids){const fld=$$('.bkx').find(x=>x.dataset.w===id),v=toRaw((fld.value||'').replace(/,/g,''),unit);if(!v){const nm=(ws.find(w=>w.id===id)||{}).name||id;$('#bke').innerHTML=notice('warn','Check the amount for '+esc(nm),'Enter a number greater than zero for every ticked wallet.');invalid(fld,$('#bke'));return false}amounts[id]=String(v);raw+=BigInt(v)}}
    else{raw=toRaw($('#bka').value.replace(/,/g,''),unit);if(!raw){$('#bke').innerHTML=notice('warn','Check the amount','Enter a number greater than zero.');invalid($('#bka'),$('#bke'));return false}}
    const r=await act('/api/bulk',{side:$('#bks').value,token:$('#bkk').value,walletIds:ids,total:String(raw),amounts,mode:$('#bkm').value,maxImpactPct:$('#bki').value.replace(/,/g,'')||undefined,onFailure:$('#bkf').checked?'stop':'continue'});if(!r.ok)return false;this.drawBulk()}}]});
  const sync=()=>{const buy=$('#bks').value==='buy';$('#bkal').textContent=buy?`Total to spend (${sq}), split equally`:'Total tokens to sell, split equally';$('#bkh').textContent=buy?'A wallet that cannot fund its share is skipped and shown, and the others still buy.':'A wallet that holds less than its share is skipped and shown, and the others still sell.'};
  const mode=()=>{const each=$('#bkd').value==='each';$$('.bkx').forEach(x=>{x.style.display=each?'':'none'});$('#bkaw').style.display=each?'none':''};$('#bkd').onchange=mode;$('#bks').onchange=sync;sync();mode()},
twapHtml(){return `<div class="panel stack" id="twp"><div class="row sb"><div><h2>TWAP orders</h2><p class="muted" style="margin:4px 0 0">Buy or sell a larger amount in equal slices over time, so one big trade does not move the price. A TWAP spreads the timing; it does not promise an average price. A slice that cannot go in its window is skipped and shown, never made up later.</p></div><div class="row"><button class="btn sm" data-tf="300" title="Practice network only: moves the practice clock forward">Skip ahead 5 min</button><button class="btn primary" id="newtw">New TWAP order</button></div></div><div class="tw" id="twt"></div></div>`},
async drawTwap(){const h=$('#twt');if(!h)return;let t;try{t=await api('/api/twap')}catch{return}this.tw=t;
  const dur=s=>s==null?'–':s<90?`${s} s`:s<5400?`${Math.round(s/60)} min`:`${(s/3600).toFixed(1)} h`;
  if(!t.length){h.innerHTML='<div class="empty" style="padding:16px"><b>No TWAP orders</b>Use "New TWAP order" to spread a buy or sell over time.</div>';return}
  h.innerHTML=`<table class="tbl-cards"><thead><tr><th>Order</th><th>Wallet</th><th>Progress</th><th class="r">Spent</th><th class="r">Received</th><th class="r">Average price</th><th>Next slice</th><th>State</th><th></th></tr></thead><tbody>${t.map(o=>{const buy=o.side==='buy';
    return `<tr class="click" data-tw="${o.id}"><td data-l="Order">${buy?'Buy':'Sell'} ${esc(o.token)}<div class="faint" style="font-size:12px">${o.slicesTotal} slices, one every ${dur(o.intervalS)}${o.limitPrice?`, price limit ${price(o.limitPrice)}`:''}</div></td><td data-l="Wallet">${esc(walletName(o.walletId))}</td>
    <td data-l="Progress">${o.filled} of ${o.slicesTotal} traded<div class="faint" style="font-size:12px">${o.skipped?`${o.skipped} skipped`:''}${o.skipped&&o.failed?', ':''}${o.failed?`${o.failed} failed`:''}${!o.skipped&&!o.failed&&o.open?`${o.open} to go`:''}</div></td>
    <td class="r num" data-l="Spent">${secret(fa(o.spent,buy?'native':o.tokenAddr,{bare:true}))}</td><td class="r num" data-l="Received">${secret(fa(o.received,buy?o.tokenAddr:'native',{bare:true}))}</td><td class="r num" data-l="Average price">${o.avgPrice?price(o.avgPrice):'–'}</td>
    <td data-l="Next slice">${o.done||o.nextInS==null?'–':'in '+dur(o.nextInS)}</td><td data-l="State">${esc(o.statusText)}</td><td>${o.done?'':`<button class="btn sm ghost" data-tc="${o.id}">Cancel</button>`}</td></tr>`}).join('')}</tbody></table>`},
twapLog(id){const o=(this.tw||[]).find(x=>x.id===id);if(!o)return;const buy=o.side==='buy',dur=s=>Math.abs(s)<90?`${Math.abs(s)} s`:`${Math.round(Math.abs(s)/60)} min`;
  const ST={pending:'Waiting',inflight:'Sent, confirming',filled:'Traded',failed:'Failed',skipped:'Skipped'};
  modal({title:`${buy?'Buy':'Sell'} ${esc(o.token)} · TWAP`,drawer:true,body:`<div class="stack">${o.refused?notice('error','Nothing was traded',`<div>${esc(o.refused)}.</div>`):notice(o.done?'plain':'info','What this order is doing',`<div>${esc(o.statusText)}.</div><div class="faint" style="margin-top:4px">${o.filled} of ${o.slicesTotal} slices traded. Each slice is a normal trade from this wallet, checked against its limits.</div>`)}
  <div class="tw"><table><thead><tr><th>Slice</th><th class="r">Amount</th><th>State</th><th>Note</th></tr></thead><tbody>${o.slices.map(x=>`<tr><td>${x.n}</td><td class="r num">${secret(fa(x.amount,buy?'native':o.tokenAddr,{bare:true}))}</td><td>${ST[x.status]||x.status}</td><td class="faint">${esc(x.reason||x.waiting||(x.status==='pending'?(x.dueInS>0?`due in ${dur(x.dueInS)}`:'due now'):''))}</td></tr>`).join('')}</tbody></table></div></div>`})},
newTwap(){const sq=QSYM();
  modal({title:'New TWAP order',body:`<div class="stack"><div class="row"><div><label for="tws">Direction</label><select id="tws"><option value="buy">Buy</option><option value="sell">Sell</option></select></div><div style="flex:1"><label for="twk">Token</label><select id="twk">${tokOpts()}</select></div></div>
  <div><label for="tww">Wallet</label><select id="tww">${wOpts('w1')}</select></div><div><label for="twa" id="twal">Total to spend (${sq})</label><input id="twa" inputmode="numeric" placeholder="e.g. 40000"></div>
  <div class="row"><div><label for="twn">Number of slices</label><input id="twn" inputmode="numeric" value="4"></div><div><label for="twi">One slice every</label><select id="twi"><option value="60">1 minute</option><option value="300" selected>5 minutes</option><option value="900">15 minutes</option><option value="3600">1 hour</option></select></div></div>
  <div><label for="twl" id="twll">Highest price you will pay (optional)</label><input id="twl" inputmode="decimal" placeholder="no limit"></div>
  <label class="row" style="gap:8px"><input type="checkbox" id="twj"> Vary the timing a little so slices are not exactly regular</label><label class="row" style="gap:8px"><input type="checkbox" id="twf"> Stop the whole order if one slice fails</label>
  <p class="muted" id="twh"></p><div id="twe"></div></div>`,
  actions:[{label:'Cancel',cls:'ghost'},{label:'Start order',cls:'primary',fn:async()=>{const buy=$('#tws').value==='buy',raw=toRaw($('#twa').value.replace(/,/g,''),buy?'native':$('#twk').value);
    if(!raw){$('#twe').innerHTML=notice('warn','Check the amount','Enter a number greater than zero.');invalid($('#twa'),$('#twe'));return false}
    const r=await act('/api/twap',{side:$('#tws').value,token:$('#twk').value,walletId:$('#tww').value,total:String(raw),slices:Number($('#twn').value),intervalS:Number($('#twi').value),limitPrice:$('#twl').value.replace(/,/g,'')||undefined,jitterPct:$('#twj').checked?30:undefined,onFailure:$('#twf').checked?'stop':'continue'});if(!r.ok)return false;this.drawTwap()}}]});
  const sync=()=>{const buy=$('#tws').value==='buy',n=Number($('#twn').value)||0,i=Number($('#twi').value);$('#twal').textContent=buy?`Total to spend (${sq})`:'Total tokens to sell';$('#twll').textContent=buy?'Highest price you will pay (optional)':'Lowest price you will accept (optional)';
    $('#twh').textContent=n>=2?`The first slice goes now, then ${n-1} more, one every ${i>=3600?'hour':i/60+' min'}. About ${Math.round((n-1)*i/60)} minutes in all. The wallet must hold the whole amount now.`:'Use at least 2 slices.'};
  ['#tws','#twn','#twi'].forEach(x=>{$(x).oninput=sync;$(x).onchange=sync});sync()},

async log(id){
  if(id==='__copy')return go('copy');
  const o=(this.ord||[]).find(x=>x.id===id);if(!o)return;let txs=[];try{txs=await api('/api/txs')}catch{}
  const mine=txs.filter(t=>t.key.startsWith(`order:${id}:`));
  const reason=o.status==='active'?`Checked on every new block (now block ${S.ov.block}). ${o.statusText}.`:o.statusText;
  modal({title:`${KIND[o.kind]} · ${esc(o.token)}`,drawer:true,body:`<div class="stack">${ctxStrip({token:o.token,chain:NET(),wallet:walletName(o.walletId),limit:o.kind==='limit_buy'?fa(o.amount,'native'):fa(o.amount,o.tokenAddr),status:ORDER_CHIP[o.status]?.[1]||o.status})}
  <h3>Execution log</h3>${notice(o.status==='failed'?'error':o.status==='active'?'info':'plain','What the rule is doing',`<div>${esc(reason)}</div><div class="faint" style="margin-top:4px">Condition: ${esc(o.label)}. Attempts so far: ${o.attempts}.</div>`)}
  ${o.oco?notice('plain','Linked pair',`This rule shares one balance with its partner (${esc(o.oco)}). When one runs, the other is cancelled, so the balance is never sold twice.`):''}
  ${mine.length?mine.map(t=>txCard(t)).join(''):`<div class="empty" style="padding:16px"><b>No trade sent yet</b>The rule has not triggered. It acts only when the condition is met and the pool can fill it.</div>`}</div>`})},
newRule(){const L=isLive(),pu=L?` (${QSYM()} per USDC)`:` (SIM)`;
  const H={bracket:'Sell if the price reaches your profit target, or falls to your stop. When one happens the other is cancelled.',limit_sell:'Sells when the price rises to your target.',limit_buy:'Buys when the price falls to your target.',trailing_stop:'Sells when the price falls a set percentage below its highest point since you set the rule.'};
  const F={bracket:`<div><label for="tp">Take profit price${pu}</label><input id="tp" inputmode="decimal" placeholder="1.30"></div><div><label for="sl2">Stop loss price${pu}</label><input id="sl2" inputmode="decimal" placeholder="0.85"></div>`,limit_sell:`<div><label for="pr">Sell when price reaches${pu}</label><input id="pr" inputmode="decimal"></div>`,limit_buy:`<div><label for="pr">Buy when price falls to${pu}</label><input id="pr" inputmode="decimal"></div>`,trailing_stop:`<div><label for="tr">Trail by (%)</label><input id="tr" inputmode="decimal" placeholder="10"></div>`};
  modal({title:'New rule',body:`<div class="stack"><div><label for="ok">Rule type</label><select id="ok"><option value="bracket">Take profit and stop loss together</option>${L?'':'<option value="limit_sell">Limit sell</option>'}<option value="limit_buy">Limit buy</option><option value="trailing_stop">Trailing stop</option></select></div>
  <div><label for="ow">Wallet</label><select id="ow">${wOpts('w1')}</select></div><div><label for="otk">Token</label><select id="otk">${tokOpts()}</select></div>
  <div><label for="oa" id="oal">Amount of tokens</label><input id="oa" inputmode="${L?'decimal':'numeric'}" placeholder="${L?'e.g. 100':'e.g. 4000'}"></div><div id="of" class="stack"></div><p class="muted" id="oh"></p><div id="oe"></div></div>`,
  actions:[{label:'Cancel',cls:'ghost'},{label:'Place rule',cls:'primary',fn:async()=>{const k=$('#ok').value,v=i=>$(i)?.value;const need=k==='bracket'?[v('#tp'),v('#sl2')]:k==='trailing_stop'?[v('#tr')]:[v('#pr')];
    if(!$('#oa').value||need.some(x=>!x)){$('#oe').innerHTML=notice('warn','Fill in every field','An amount and the price condition are both required.');return false}
    const amtRaw=toRaw($('#oa').value.replace(/,/g,''),k==='limit_buy'?'native':$('#otk').value);if(!amtRaw){$('#oe').innerHTML=notice('warn','Check the amount','Enter a number greater than zero.');invalid($('#oa'),$('#oe'));return false}
    const r=await act('/api/orders',{kind:k,token:$('#otk').value,walletId:$('#ow').value,amount:String(amtRaw),price:v('#pr'),tp:v('#tp'),sl:v('#sl2'),trailPct:v('#tr')});if(!r.ok)return false;this.tick()}}]});
  const sync=()=>{const k=$('#ok').value;$('#oh').textContent=H[k];$('#of').innerHTML=F[k];$('#oal').textContent=k==='limit_buy'?`Amount to spend (${QSYM()})`:isLive()?'Amount of USDC':'Amount of tokens'};$('#ok').onchange=sync;sync();
}};

/* ---------- Copy trade ---------- */
const copyState=c=>!S.online?'error':!c.enabled?'paused':c.cfg.sides==='sell'?'entries-paused':'active';
const copyChip=c=>{const s=copyState(c);const w=S.ov.wallets.find(x=>x.id===c.cfg.walletId);if(w?.policy.automationPaused)return `<span class="chip bad">Error: wallet automation is off</span>`;return {active:'<span class="chip ok">Active</span>','entries-paused':'<span class="chip warn">Paused: new entries</span>',paused:'<span class="chip warn">Paused</span>',error:'<span class="chip bad">Error: disconnected</span>'}[s]};
V.copy={title:'Copy trade',needsData:true,
html(){return practiceNote()+head('Copy trade','Mirror the swaps of wallets you follow. Only tokens you bought because of a leader are ever sold when that leader sells.',`<button class="btn primary" id="setup">Follow a wallet</button>`)+`<div class="stack"><div class="panel flush"><div class="tw" id="cl">${skeleton(2)}</div></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr))"><div class="panel stack"><h2>Why trades were skipped</h2><div id="cg"></div></div><div class="panel stack"><h2>Practice controls</h2><p class="muted">Simulate the leader trading to see your rules decide.</p><div><label for="ca">Leader's trade size (SIM)</label><input id="ca" value="20000" inputmode="numeric"></div><div class="row"><button class="btn sm" data-l="buy">Leader buys MEME</button><button class="btn sm" data-l="sell">Leader sells MEME</button><button class="btn sm" data-l="transfer">Leader transfers (ignored)</button></div></div></div></div>`},
mount(){trackMount();$('#setup').onclick=()=>this.wizard();$('#view').addEventListener('click',async e=>{const b=e.target.closest('[data-l]');if(b){const l=b.dataset.l;await act('/api/copy/leader',{side:l==='transfer'?'buy':l,kind:l==='transfer'?'transfer':'swap',amount:$('#ca').value});this.tick()}const r=e.target.closest('tr[data-lead]');if(r)this.drawer()});this.tick()},
async tick(){S.trackDraw&&S.trackDraw(false);const el=$('#cl');if(!el)return;try{this.c=await api('/api/copy')}catch{el.innerHTML=failBox('copy trading');return}const c=this.c;
  const last=c.log[0];const pnl=BigInt(c.unrealised||0);
  el.innerHTML=`<table class="tbl-cards"><thead><tr><th>Leader</th><th>Your wallet</th><th class="r">Allocation / budget left</th><th>Copy settings</th><th class="r">Your P&amp;L</th><th>Last copied action</th><th>State</th></tr></thead><tbody><tr class="click" data-lead="1"><td data-l="Leader"><b>whale.sim</b><div>${chainChip('practice')}</div></td><td data-l="Wallet">${esc(walletName(c.cfg.walletId))}</td><td data-l="Budget" class="r num">${fmt(c.cfg.maxPerLeader)} SIM<div class="muted" style="font-size:12px">${fmt(BigInt(c.cfg.maxPerLeader)-BigInt(c.budgetUsed||0))} left</div></td><td data-l="Settings">${c.cfg.mode==='fixed'?`${fmt(c.cfg.fixed)} SIM per copy`:`${c.cfg.ratioPct}% of leader`}<div class="muted" style="font-size:12px">${{both:'Buys and sells',buy:'Buys only',sell:'Sells only'}[c.cfg.sides]}</div></td><td data-l="P&L" class="r num ${pnl>=0n?'up':'dn'}">${secret((pnl>=0n?'+':'')+fmt(pnl)+' SIM')}<div class="muted" style="font-size:12px">open positions only</div></td><td data-l="Last action" class="muted">${last?esc(last.text):'Nothing copied yet'}</td><td data-l="State">${copyChip(c)}</td></tr></tbody></table>`;
  const g=$('#cg');g.innerHTML=c.log.length?c.log.map(l=>notice(l.decision==='emit'?'ok':'plain','',esc(l.text))).join('<div style="height:6px"></div>'):`<div class="empty" style="padding:16px"><b>Nothing decided yet</b>When the leader trades, each decision appears here in plain words, including why a trade was skipped.</div>`;
  if(dlg.open&&dlg.classList.contains('drawer')&&this.open)this.drawer(true)},
drawer(refresh){const c=this.c;if(!c)return;this.open=true;const paused=copyState(c)!=='active';
  if(refresh&&!$('#cdr'))return;
  modal({title:'whale.sim',drawer:true,onClose:()=>this.open=false,body:`<div class="stack" id="cdr">${ctxStrip({token:'Leader whale.sim',chain:NET(),wallet:walletName(c.cfg.walletId),limit:`${fmt(c.cfg.maxPerLeader)} SIM cap`,status:{active:'Active','entries-paused':'Paused',paused:'Paused',error:'Error'}[copyState(c)]})}
  <div class="grid" style="grid-template-columns:1fr 1fr"><div class="panel"><h3>Leader's own results ${sampleTag}</h3><p class="num" style="font-size:20px;margin-top:6px">+18.4%</p><p class="faint" style="font-size:12px">The leader's 30-day trading, before your delays and fees. It is not what you earned.</p></div>
  <div class="panel"><h3>Your copied results</h3><p class="num ${BigInt(c.unrealised||0)>=0n?'up':'dn'}" style="font-size:20px;margin-top:6px">${secret(fmt(c.unrealised||0)+' SIM')}</p><p class="faint" style="font-size:12px">Open copied positions only, at today's pool price. Cost in use: ${secret(fmt(c.budgetUsed||0))} SIM.</p></div></div>
  <div class="kv"><span>Per-token cap</span><b class="num">${fmt(c.cfg.maxPerToken)} SIM</b></div><div class="kv"><span>Daily limit</span><b class="num">${fmt(c.cfg.dailyLimit)} SIM</b></div><div class="kv"><span>Price-move limit</span><b>${c.cfg.maxDeviationPct}%</b></div><div class="kv"><span>Follows leader exits</span><b>${c.cfg.followLeaderExit?'Yes':'No'}</b></div>
  <div class="kv"><span>Currently held because of this leader</span><span>${c.inventory.length?c.inventory.map(i=>`${secret(fmt(i.qty))} ${esc(i.sym)}`).join(', '):'Nothing'}</span></div>
  <div class="row" style="margin-top:8px">${paused?`<button class="btn primary" id="resume">Resume strategy</button>`:`<button class="btn danger" id="pausebtn2">Pause strategy</button>`}<button class="btn" id="edit">Edit settings</button></div></div>`});
  const p=$('#pausebtn2');if(p)p.onclick=()=>this.pause();const r=$('#resume');if(r)r.onclick=async()=>{await api('/api/copy',{enabled:true,sides:'both'});toast('success','Strategy resumed','New entries are on again, within your limits.');closeModal();this.tick()};$('#edit').onclick=()=>this.wizard(true)},
pause(){modal({title:'Pause strategy',body:`<div class="stack"><p class="muted">Choose what stops. These choices are separate on purpose.</p>
  <label style="display:flex;gap:10px;color:var(--ink)"><input type="radio" name="pm" value="entries" checked style="width:auto;min-height:0;margin-top:3px"><span><b>Pause new entries</b><br><span class="muted">Stop copying the leader's buys. Positions you already hold keep following the leader's sells.</span></span></label>
  <label style="display:flex;gap:10px;color:var(--ink)"><input type="radio" name="pm" value="all" style="width:auto;min-height:0;margin-top:3px"><span><b>Pause everything</b><br><span class="muted">Ignore all leader trades. Existing positions then stay open until you sell them yourself.</span></span></label>
  ${notice('plain','Exit rules are separate','Stop losses and take profits you set stay active. Cancel them on the Orders page if you want them gone.')}</div>`,
  actions:[{label:'Cancel',cls:'ghost'},{label:'Pause strategy',cls:'primary',fn:async()=>{const m=document.querySelector('input[name=pm]:checked').value;await api('/api/copy',m==='entries'?{enabled:true,sides:'sell',followLeaderExit:true}:{enabled:false});toast('warn','Strategy paused',m==='entries'?'No new copy buys. Exits still follow the leader.':'All leader trades are ignored.');closeModal();this.tick()}}]})},
wizard(editing){
  const c=this.c;const W={leader:'whale.sim',wallet:c?.cfg.walletId||'w1',mode:c?.cfg.mode||'proportional',val:c?(c.cfg.mode==='fixed'?String(c.cfg.fixed):String(c.cfg.ratioPct)):'20',sides:'both',max:String(c?.cfg.maxPerToken||40000),day:String(c?.cfg.dailyLimit||120000),dev:String(c?.cfg.maxDeviationPct||15)};
  const steps=['Choose leader','Choose wallet','Set sizing','Set limits','Review','Activate'];let i=0;
  const draw=()=>{const body={
    0:`<div class="stack"><label style="display:flex;gap:10px;color:var(--ink);border:1px solid var(--blue);border-radius:8px;padding:12px"><input type="radio" checked style="width:auto;min-height:0"><span><b>whale.sim</b> ${chainChip('practice')}<br><span class="muted">A simulated leader for practice.</span></span></label><div><label for="la">Or paste a leader address</label><input id="la" disabled placeholder="Needs a live chain feed"><p class="hint faint">Following real wallets needs a live data connection, which practice mode does not have.</p></div></div>`,
    1:`<div><label for="cw">Your wallet</label><select id="cw">${wOpts(W.wallet)}</select><p class="hint faint">Copies are bought from this wallet, within its signing limits.</p></div>`,
    2:`<div class="stack"><div><label for="cm">How much to copy</label><select id="cm"><option value="proportional" ${W.mode==='proportional'?'selected':''}>A share of the leader's trade size</option><option value="fixed" ${W.mode==='fixed'?'selected':''}>The same fixed amount every time</option></select></div><div><label for="cv" id="cvl"></label><input id="cv" inputmode="decimal" value="${esc(W.val)}"></div><div><label for="cs">Copy</label><select id="cs"><option value="both">Buys and sells</option><option value="buy">Buys only</option><option value="sell">Sells only</option></select></div></div>`,
    3:`<div class="stack"><div><label for="cx">Maximum per token (SIM)</label><input id="cx" inputmode="numeric" value="${esc(W.max)}"></div><div><label for="cd">Daily limit (SIM)</label><input id="cd" inputmode="numeric" value="${esc(W.day)}"></div><div><label for="cp2">Skip if price moved more than (%)</label><input id="cp2" inputmode="decimal" value="${esc(W.dev)}"><p class="hint faint">You will see "Skipped: price moved beyond your ${esc(W.dev)}% limit." when this applies.</p></div></div>`,
    4:`<div class="stack">${ctxStrip({token:'Leader trades',chain:NET(),wallet:walletName(W.wallet),limit:`${fmt(W.max)} SIM per token`,status:'Not active yet'})}<div class="kv"><span>Leader</span><b>${esc(W.leader)}</b></div><div class="kv"><span>Sizing</span><b>${W.mode==='fixed'?`${fmt(W.val)} SIM per copy`:`${W.val}% of leader's trade`}</b></div><div class="kv"><span>Copies</span><b>${{both:'Buys and sells',buy:'Buys only',sell:'Sells only'}[W.sides]}</b></div><div class="kv"><span>Daily limit</span><b>${fmt(W.day)} SIM</b></div><div class="kv"><span>Price-move limit</span><b>${W.dev}%</b></div>${notice('plain','','You can pause any time. Pausing stops new entries without touching positions or exit rules.')}</div>`,
    5:`<div class="empty"><b>Ready to activate</b>Copying starts with the next leader trade. Nothing is bought until the leader trades and passes your limits.</div>`}[i];
    modal({title:editing?'Edit copy settings':'Follow a wallet',body:`<ol class="steps">${steps.map((s,k)=>`<li class="${k===i?'on':k<i?'done':''}"><b>${k<i?'✓':k+1}</b>${s}</li>`).join('')}</ol>${body}`,
    actions:[{label:i?'Back':'Cancel',cls:'ghost',keep:true,fn:()=>{if(!i)return closeModal();save();i--;draw();return false}},{label:i===5?'Activate':'Next',cls:'primary',keep:true,fn:async()=>{save();if(i===3&&!Number(W.max)){toast('warn','Set a limit','Enter a maximum per token above zero.');return false}if(i<5){i++;draw();return false}
      const r=await act('/api/copy',{enabled:true,walletId:W.wallet,mode:W.mode,[W.mode==='fixed'?'fixed':'ratioPct']:W.val,sides:W.sides,maxPerToken:W.max,dailyLimit:W.day,maxDeviationPct:W.dev});if(r.ok===false)return false;closeModal();this.tick()}}]});
    if(i===2){const s=()=>$('#cvl').textContent=$('#cm').value==='fixed'?'Amount per copy (SIM)':"Share of leader's trade (%)";$('#cm').onchange=s;s();$('#cs').value=W.sides}};
  const save=()=>{const g=id=>$(id)?.value;if(g('#cw'))W.wallet=g('#cw');if(g('#cm')){W.mode=g('#cm');W.val=g('#cv');W.sides=g('#cs')}if(g('#cx')){W.max=g('#cx');W.day=g('#cd');W.dev=g('#cp2')}};
  draw()}};

/* ---------- Sniper ---------- */
const SN_COLS=[['scheduled','Scheduled'],['watching','Watching'],['ready','Ready'],['submitted','Submitted'],['completed','Completed'],['failed','Failed']];
const EV={detected:'Launch detected',submitted:'Buy submitted',confirmed:'Buy confirmed',failed:'Buy failed'};
V.sniper={title:'Sniper',needsData:true,
html(){return practiceNote()+head('Sniper',S.realInfo?.enabled?'Real launches read from chain, with a dry run of example sniper rules. Nothing is bought here.':'Prepare buys for a token before it launches, with limits you set in advance.',`<button class="btn primary" id="newsn">New sniper</button>`)+
  `${S.realInfo?.enabled?'<div id="nb"></div><div id="lb" style="margin-top:12px">'+skeleton(3)+'</div>':`${notice('warn','The board is a preview','Practice mode does not run scheduled snipes. The cards show how a sniper would be laid out; the Launch check below is real and runs on the practice network.')}
  <div class="kan" style="margin-top:12px" role="list">${SN_COLS.map(([k,l])=>{const cs=(S.snipes||SAMPLE_SNIPES).filter(c=>c.col===k);return `<section class="kcol" role="listitem" aria-label="${l}"><h3>${l}<span class="chip">${cs.length}</span></h3><div class="cl">${cs.length?cs.map(c=>`<div class="kc"><div class="row sb"><b>${esc(c.name)}</b>${sampleTag}</div>${c.event?`<div class="ev ${c.event}">${EV[c.event]}</div>`:''}<div class="kv" style="padding:0"><span>Wallets</span><span>${c.wallets.map(esc).join(', ')}</span></div><div class="kv" style="padding:0"><span>Max spend</span><b class="num">${secret(fmt(c.max))} SIM</b></div><div class="kv" style="padding:0"><span>Condition</span><span>${esc(c.liq)}</span></div><div class="kv" style="padding:0"><span>Simulation</span><span>${c.sim||'Not run yet'}</span></div><div class="kv" style="padding:0"><span>Exit rules</span><span style="text-align:right">${esc(c.exit)}</span></div>${c.why?notice('error','',esc(c.why)):''}</div>`).join(''):`<div class="empty" style="padding:16px"><b>Empty</b></div>`}</div></section>`}).join('')}</div>`}
  <div class="panel stack" style="margin-top:14px"><h2>Launch check</h2><p class="muted">Dry-runs a buy and the sell back on a throwaway wallet: can you buy, can you sell, what does it cost.</p><div class="row"><div style="min-width:200px"><label for="st">Token</label><select id="st">${tokOpts()}</select></div><div><label for="sa">Test amount (SIM)</label><input id="sa" value="10000" inputmode="numeric"></div><div style="align-self:end"><button class="btn primary" id="sg">Run launch check</button></div></div><div id="sr" aria-live="polite"></div></div>`},
mount(){S.snipes=S.snipes||SAMPLE_SNIPES.map(x=>({...x}));$('#newsn').onclick=()=>this.create();if(S.realInfo?.enabled){S.launchAt=0;this.tick()}
  $('#sg').onclick=async()=>{const sr=$('#sr');sr.innerHTML=skeleton(1);let d;try{d=await api('/api/launch-check',{token:$('#st').value,amount:$('#sa').value})}catch{sr.innerHTML=notice('error','Check did not run','The practice network is not answering. Nothing was sent.');return}
    const s=d.sim,row=(ok,t,x)=>notice(ok?'ok':'error',t,esc(x));
    sr.innerHTML=`<h3 style="margin-top:6px">${esc(d.sym)}: simulated at block ${s.block} (${new Date().toLocaleTimeString()})</h3>`+(s.restrictedBlocksRemaining>0?row(false,'Trading is not open yet',`About ${s.restrictedBlocksRemaining} blocks until it opens (block ${s.tradingOpenBlock}).`):'')+row(s.buy.feasible,s.buy.feasible?'Buying works':'Buying fails',s.buy.feasible?`Tax on buy: ${(s.buy.taxBps||0)/100}%. Price impact: ${((s.buy.priceImpactBps||0)/100).toFixed(2)}%.`:(s.buy.reason||''))+row(s.sell.feasible,s.sell.feasible?'Selling works':'Selling fails',s.sell.feasible?`Tax on sell: ${(s.sell.taxBps||0)/100}%.`:(s.sell.reason||''))+(s.limitations||[]).map(l=>notice('plain','',esc(l))).join('')};
  const b=$('#view');b.onclick=e=>{};},
live(){if(S.es||!S.realInfo?.enabled||typeof EventSource==='undefined')return;S.liveItems=S.liveItems||[];S.ls=S.ls||{state:'connecting',n:0};
  const es=new EventSource('/api/launches/stream');S.es=es;
  es.addEventListener('hello',e=>{const d=JSON.parse(e.data);S.ls={...S.ls,...d.status};S.liveItems=d.items;this.boardFill();V.discover.strip&&V.discover.strip()});
  es.addEventListener('launch',e=>{const it=JSON.parse(e.data);S.ls.n=(S.ls.n||0)+1;S.ls.state='open';S.liveItems=S.liveItems.filter(x=>x.sig!==it.sig);S.liveItems.unshift(it);if(S.liveItems.length>500)S.liveItems.length=500;this.boardAdd(it);V.discover.strip&&V.discover.strip()});
  es.addEventListener('status',e=>{S.ls={...S.ls,...JSON.parse(e.data)};this.boardStatus()});
  es.onerror=()=>{S.ls={...S.ls,state:'reconnecting'};this.boardStatus()}},
/* "New on Solana": every token the live stream has seen, newest first (Pump.fun creations and Raydium pool creations). */
boardInit(){const nb=$('#nb');if(!nb||$('#nbt'))return;S.nbq=S.nbq||'';S.nbPause=false;const th='style="position:sticky;top:0;background:var(--panel)"';
  nb.innerHTML=`<div class="panel stack"><div class="row sb"><h2 style="margin:0">New on Solana</h2><div class="row"><input id="nbq" type="search" placeholder="Filter by name, symbol or address" aria-label="Filter new tokens" style="min-width:240px" value="${esc(S.nbq)}"><button class="btn sm" id="nbp">Pause</button></div></div><div id="nbs"></div><div class="tw" style="max-height:62vh;overflow:auto"><table id="nbtab"><thead><tr><th ${th}>Age</th><th ${th}>Token</th><th ${th}>Where</th><th ${th}>Address</th><th ${th}>Created by</th><th ${th}>Mint check</th></tr></thead><tbody id="nbt"></tbody></table><div id="nbe"></div></div></div>`;
  $('#nbq').oninput=e=>{S.nbq=e.target.value;this.boardFill()};
  $('#nbp').onclick=()=>{S.nbPause=!S.nbPause;$('#nbp').textContent=S.nbPause?'Resume':'Pause';if(!S.nbPause)this.boardFill();this.boardStatus()};
  nb.onclick=e=>{const c=e.target.closest('[data-copy]');if(c){navigator.clipboard?.writeText(c.dataset.copy).then(()=>toast('success','Address copied',esc(short(c.dataset.copy))),()=>{})}};
  if(!S.nbTimer)S.nbTimer=setInterval(()=>{if(S.view!=='sniper'){clearInterval(S.nbTimer);S.nbTimer=0;return}const now=Date.now();$$('#nbt td.age').forEach(td=>{td.textContent=V.sniper.age(now-Number(td.dataset.seen))})},1000);
  this.boardFill()},
age(ms){const s=Math.max(0,Math.floor(ms/1000));return s<60?s+'s':s<3600?Math.floor(s/60)+'m':Math.floor(s/3600)+'h'},
boardRow(it){const v={'no-flags':'<span class="chip ok">No flags</span>',warn:'<span class="chip warn">Caution</span>',quarantined:'<span class="chip warn" title="Token-2022 mints are not understood by this engine">Unusual</span>',blocked:'<span class="chip bad">Blocked</span>',unchecked:'<span class="chip">Not checked</span>'}[it.verdict]||'',
  pump=it.pad==='pump-fun',url=pump?`https://pump.fun/coin/${it.contract}`:`https://dexscreener.com/solana/${it.pool}`;
  return `<tr data-sig="${esc(it.sig||it.id)}"><td class="age num" data-seen="${it.seenAt||Date.now()}">${this.age(Date.now()-(it.seenAt||Date.now()))}</td><td><b>${esc(it.sym)}</b><div class="faint" style="font-size:12px">${esc(it.name)}</div></td><td>${pump?'Pump.fun':'Raydium'}</td><td><a href="${esc(url)}" target="_blank" rel="noopener noreferrer" title="${esc(it.contract)}">${esc(short(it.contract))}</a> <button class="btn sm" data-copy="${esc(it.contract)}" aria-label="Copy address">Copy</button></td><td class="faint" title="${esc(it.creator||'')}">${it.creator?esc(short(it.creator)):'–'}</td><td>${v}</td></tr>`},
boardMatch(it){const q=(S.nbq||'').trim().toLowerCase();return !q||[it.sym,it.name,it.contract,it.creator||''].some(x=>String(x).toLowerCase().includes(q))},
boardFill(){const t=$('#nbt');if(!t||S.nbPause)return;const rows=(S.liveItems||[]).filter(i=>this.boardMatch(i)).slice(0,300);t.innerHTML=rows.map(i=>this.boardRow(i)).join('');$('#nbe').innerHTML=rows.length?'':`<div class="empty" style="padding:16px"><b>${(S.liveItems||[]).length?'No match':'Waiting for the first launch'}</b>${(S.liveItems||[]).length?'Clear the filter to see every token.':'New tokens appear here as soon as they are confirmed.'}</div>`;this.boardStatus()},
boardAdd(it){const t=$('#nbt');if(!t||S.nbPause){this.boardStatus();return}if(this.boardMatch(it)){t.insertAdjacentHTML('afterbegin',this.boardRow(it));while(t.children.length>300)t.lastElementChild.remove();$('#nbe').innerHTML=''}this.boardStatus()},
boardStatus(){const el=$('#nbs');if(!el)return;const ls=S.ls||{},fs=ls.feeds||[],ok=ls.state==='open'&&fs.some(f=>f.subscribed);
  el.innerHTML=(ok?`<p class="muted" style="margin:0"><span class="chip ok">Live</span> ${(S.liveItems||[]).length} tokens kept (newest 500, last 24 hours). ${ls.n||0} new since you opened this page${S.nbPause?' · <b>paused: new rows are held back until you resume</b>':''}. Confirmed, not finalized; nothing is seen before it is mined.${ls.gaps?` The connection dropped ${ls.gaps} time${ls.gaps>1?'s':''}; launches during a drop are missing.`:''}</p>`:`<p class="muted" style="margin:0"><span class="chip warn">${ls.state==='stopped'?'Off':'Not connected'}</span> ${esc(ls.lastError||'Connecting…')} Tokens already seen are still listed.</p>`)+((S.liveItems||[]).some(i=>i.pad==='pump-fun')?'<p class="faint" style="margin:4px 0 0;font-size:12px">Pump.fun tokens trade on a bonding curve that this engine cannot trade yet, so they are for watching only.</p>':'')},
async tick(){const el=$('#lb');if(!el)return;V.sniper.boardInit();V.sniper.live();if(S.launches&&Date.now()-S.launchAt<45000)return;S.launchAt=Date.now();let d;try{d=await api('/api/launches')}catch{if(!S.launches)el.innerHTML=failBox('launches');return}S.launches=d;this.drawL(el,d)},
drawL(el,d){const cols=[['would','Would buy under the example rules','Meets liquidity, age and risk rules and trades on a venue this engine supports.'],['skip','Skipped by the checks','Fails a rule. The reason is on each card.'],['no','Cannot be traded here','Launched on a venue this engine does not trade.']];
  const col=i=>!i.executable?'no':i.dryRun.wouldBuy?'would':'skip';const vchip=v=>({'no-flags':'<span class="chip ok">No flags</span>',warn:'<span class="chip warn">Caution</span>',quarantined:'<span class="chip warn">Unusual</span>',blocked:'<span class="chip bad">Blocked</span>',unchecked:'<span class="chip">Not checked</span>'}[v]);
  const items=[...(d.items||[])].sort((a,b)=>(a.ageMin??1e9)-(b.ageMin??1e9)).slice(0,60);
  el.innerHTML=notice('plain','Real data, read-only',`<div>Launches below are real, read from the chain and public market data (${esc((d.notes||[]).length?'see notes at the bottom':'no gaps reported')}). The sniper never buys here: this is what it <i>would</i> do under example rules (pool of at least $5,000, no freeze authority, listed in the last 24 hours).</div>`)+
  `<div class="kan k3" style="margin-top:12px" role="list">${cols.map(([k,l,h])=>{const cs=items.filter(i=>col(i)===k);return `<section class="kcol" role="listitem" aria-label="${l}"><h3>${l}<span class="chip">${cs.length}</span></h3><p class="hint faint" style="margin:0 0 8px">${h}</p><div class="cl">${cs.length?cs.map(c=>{const known=(S.real||[]).find(t=>t.contract===c.contract);return `<div class="kc"><div class="row sb"><b>${esc(c.sym)}</b>${chainChip(c.chain)}</div><div class="faint" style="font-size:12px">${esc(c.name)} · ${esc(c.venue)}${c.pad?' · '+esc((LAUNCHPADS[c.pad]||{}).name||c.pad):''}</div><div class="kv" style="padding:0"><span>Pool age</span><span>${ago(c.ageMin)}</span></div><div class="kv" style="padding:0"><span>Liquidity</span><b class="num">${c.liqUsd==null?'unknown':'$'+compact(c.liqUsd)}</b></div><div class="kv" style="padding:0"><span>Risk check</span><span>${vchip(c.verdict)}</span></div>${c.flags.length?`<div class="faint" style="font-size:12px;margin-top:4px">${c.flags.slice(0,2).map(esc).join('<br>')}</div>`:''}<div style="font-size:12.5px;margin-top:6px;color:var(--ink)">${esc(c.dryRun.why)}</div>${known?`<button class="btn" style="margin-top:8px" data-open="${esc(known.id)}">Open token</button>`:`<div class="faint" style="font-size:12px;margin-top:6px" title="${esc(c.contract)}">${short(c.contract)}</div>`}</div>`}).join(''):`<div class="empty" style="padding:16px"><b>Nothing here</b></div>`}</div></section>`}).join('')}</div>`+
  ((d.notes||[]).length?`<div class="panel" style="margin-top:12px"><h3>Notes</h3>${d.notes.map(n=>`<p class="muted" style="margin:4px 0">${esc(n)}</p>`).join('')}</div>`:'')+(d.error?notice('warn','Some data could not be refreshed',esc(d.error)):'');
  el.onclick=e=>{const b=e.target.closest('[data-open]');if(b){S.token=b.dataset.open;go('trade')}}},
create(){modal({title:'New sniper',body:`<div class="stack"><div><label for="nn">Name</label><input id="nn" placeholder="Launch watch G"></div><div><label>Wallets</label>${S.ov.wallets.map(w=>`<label style="display:flex;gap:8px;color:var(--ink)"><input type="checkbox" class="nw" value="${esc(w.name)}" ${w.id==='w1'?'checked':''} style="width:auto;min-height:0">${esc(w.name)} · Practice network</label>`).join('')}</div>
  <div><label for="nm">Maximum spend (SIM)</label><input id="nm" inputmode="numeric" value="5000"></div><div><label for="nl">Only buy if</label><select id="nl"><option>Pool at least 10,000</option><option>Pool at least 50,000</option></select></div><div><label for="ne">Exit rules</label><select id="ne"><option>None set</option><option>Take profit +50%, stop loss -25%</option><option>Trailing stop 20%</option></select></div></div>`,
  actions:[{label:'Cancel',cls:'ghost'},{label:'Review',cls:'primary',fn:()=>{const ws=$$('.nw:checked').map(x=>x.value),m=$('#nm').value.replace(/\D/g,'');if(!ws.length||!m){toast('warn','Pick a wallet and a limit','A sniper needs at least one wallet and a maximum spend.');return false}
    const card={id:'n'+Date.now(),col:'scheduled',name:$('#nn').value||'Launch watch',wallets:ws,max:Number(m),liq:$('#nl').value,sim:null,exit:$('#ne').value,event:null};
    setTimeout(()=>modal({title:'Authorize this sniper',body:`<div class="stack">${ctxStrip({token:'Next launch you choose',chain:NET(),wallet:ws.join(', '),limit:`${fmt(m)} SIM max`,status:'Not active'})}${notice('plain','What you are authorizing',`<div>Spend up to <b style="display:inline">${fmt(m)} SIM</b> from ${esc(ws.join(' and '))}, only if ${esc(card.liq.toLowerCase())}. Exit rules: ${esc(card.exit.toLowerCase())}.</div><div>It stops on its own after one buy attempt that fills, or when you cancel it.</div>`)}${notice('warn','Preview only','Practice mode will not run this sniper. It is added to the board so you can review the layout.')}</div>`,
      actions:[{label:'Back',cls:'ghost'},{label:'Activate sniper',cls:'primary',fn:()=>{S.snipes.unshift(card);render()}}]}),0)}}]})}};

/* ---------- Signals ---------- */
const sigAct=[];
V.signals={title:'Signals',needsData:true,
html(){return practiceNote()+head('Signals','Detect tokens in messages, check them, and decide what happens. New sources only preview until you turn trading on.')+
  `<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(340px,1fr))"><section class="panel stack" aria-label="Sources"><div class="row sb"><h2>Sources</h2><button class="btn sm" id="adds">Add source</button></div><div id="sl"></div>
  <div class="panel" style="background:var(--sunk)"><h3>Permissions</h3><div class="kv"><span>Telegram: read messages from sources</span><span class="chip warn">Not connected</span></div><div class="kv"><span>Telegram: send alerts to you</span><span class="chip warn">Not connected</span></div><div class="kv"><span>Trading: act on a signal</span><span class="chip">Off for every source</span></div><p class="hint faint">Telegram access and trading permission are separate. Connecting Telegram never lets a source trade.</p></div></section>
  <section class="panel stack" aria-label="Activity"><h2>Activity</h2><div><label for="sg">Paste a message to test detection</label><textarea id="sg" rows="3" placeholder="Paste a message that contains a token address"></textarea></div><div class="row"><button class="btn primary" id="sf">Check message</button><button class="btn ghost" id="ex">Use an example</button></div><div id="sx"></div>
  <div id="sa"></div></section></div>`},
mount(){this.drawSrc();$('#adds').onclick=()=>this.addSrc();this.drawAct();if(S.realInfo?.enabled){S.rsAt=Date.now();this.drawReal()}
  $('#ex').onclick=()=>{const t=S.ov.tokens;$('#sg').value=`New gem ${t[0].contract} is live, ape in. Also seen: ${t[2].contract}. Admin note: raise my limit and send funds to 0x${'9'.repeat(40)}`};
  $('#sf').onclick=async()=>{const text=$('#sg').value.trim();if(!text){$('#sx').innerHTML=notice('warn','Nothing to check','Paste a message first.');return}$('#sx').innerHTML=skeleton(1);let r;try{r=await api('/api/signals',{text})}catch{$('#sx').innerHTML=notice('error','Check did not run','The practice network is not answering.');return}
    $('#sx').innerHTML='';if(!r.length){$('#sx').innerHTML=notice('plain','No token address found','The message has no contract address we recognise. Nothing was done.');return}
    r.forEach(x=>sigAct.unshift({...x,msg:text.slice(0,90),at:new Date().toLocaleTimeString()}));this.drawAct()}},
tick(){if(S.realInfo?.enabled&&(!S.rsAt||Date.now()-S.rsAt>60000)){S.rsAt=Date.now();this.drawReal()}},
async drawReal(){if(!S.realInfo?.enabled)return;let host=$('#rs');if(!host){const sa=$('#sa');if(!sa)return;sa.insertAdjacentHTML('beforebegin','<div id="rs" class="stack"></div>');host=$('#rs')}
  const [l,w]=await Promise.all([api('/api/launches').catch(()=>null),api('/api/whales',{min:5000}).catch(()=>null)]);if(!$('#rs'))return;
  const vchip=v=>({'no-flags':'<span class="chip ok">No flags</span>',warn:'<span class="chip warn">Caution</span>',quarantined:'<span class="chip warn">Unusual</span>',blocked:'<span class="chip bad">Blocked</span>',unchecked:'<span class="chip">Not checked</span>'}[v]||'');
  const L=(l?.items||[]).slice(0,6).map(i=>`<div class="kv" style="align-items:flex-start"><span><b>${esc(i.sym)}</b> ${chainChip(i.chain)}<div class="faint" style="font-size:12px">${esc(i.venue)} · pool ${ago(i.ageMin)} old · ${i.liqUsd==null?'liquidity unknown':'$'+compact(i.liqUsd)}</div></span><span style="text-align:right">${vchip(i.verdict)}<div class="faint" style="font-size:12px;max-width:220px">${esc(i.dryRun.wouldBuy?'Would buy under example rules':i.dryRun.why.split(';')[0])}</div></span></div>`).join('');
  const W=(w?.items||[]).filter(x=>x.side==='buy').slice(0,6).map(x=>`<div class="kv"><span><b>${esc(x.sym)}</b> ${chainChip(x.chain)}<div class="faint" style="font-size:12px">${new Date(x.t).toLocaleTimeString()} · wallet ${esc(short(x.wallet))}</div></span><b class="num up">$${compact(x.usd)}</b></div>`).join('');
  host.innerHTML=`<div class="panel stack"><div class="row sb"><h2>On-chain signals</h2><span class="chip ok">Real, read-only</span></div><p class="muted">Signals found in public chain data. They name tokens; they do not trade. Anyone can launch or buy a token to make it look interesting.</p>
  <h3>New launches</h3>${L||'<p class="muted">No launches loaded yet.</p>'}<h3 style="margin-top:10px">Large buys (≥ $5,000)</h3>${W||`<p class="muted">${w?.loaded?'No large buys in the trades loaded so far.':'The trade feed is still filling (one pool every few seconds).'}</p>`}${(l?.notes||[]).map(n=>`<p class="muted" style="font-size:12.5px">${esc(n)}</p>`).join('')}</div>`},
drawSrc(){const el=$('#sl');const real=!!S.realInfo?.enabled,list=real?S.sources.filter(x=>!/^src\d$/.test(x.id)):S.sources;
  const built=real?`<div class="panel" style="background:var(--sunk)"><b>On-chain: new launches</b> <span class="chip ok">Live, read-only</span><div class="faint" style="font-size:12px">Pump.fun, Four.meme and Raydium pool creations, checked by our own mint and pool tests</div></div><div class="panel" style="background:var(--sunk)"><b>On-chain: large buys</b> <span class="chip ok">Live, read-only</span><div class="faint" style="font-size:12px">Buys of $5,000 or more on the top real pools (third-party trade feed)</div></div>`:'';
  el.innerHTML=built+(list.length?list.map(s=>`<div class="panel" style="background:var(--sunk)"><div class="row sb"><div><b>${esc(s.name)}</b> ${sampleTag}<div class="faint" style="font-size:12px">${esc(s.kind)} · preset: ${esc(s.preset)} · last message ${esc(s.last)}</div></div><span class="chip ${s.mode==='preview'?'info':'warn'}">${s.mode==='preview'?'Preview only':'Auto-trading armed'}</span></div><div class="row" style="margin-top:8px">${s.mode==='preview'?`<button class="btn sm" data-arm="${s.id}">Turn on auto-trading</button>`:`<button class="btn sm" data-arm="${s.id}">Back to preview only</button>`}<button class="btn sm ghost" data-rm="${s.id}">Remove</button></div></div>`).join(''):(real?'':`<div class="empty"><b>No sources yet</b>Add a Telegram channel to start previewing signals.</div>`));
  el.onclick=e=>{const a=e.target.closest('[data-arm]'),r=e.target.closest('[data-rm]');const sv=()=>{store.set('sources',S.sources);this.drawSrc()};
    if(r){S.sources=S.sources.filter(x=>x.id!==r.dataset.rm);sv()}
    if(a){const s=S.sources.find(x=>x.id===a.dataset.arm);if(s.mode!=='preview'){s.mode='preview';sv();return}
      modal({title:'Turn on auto-trading?',body:`<div class="stack">${notice('warn','Messages can be wrong or hostile',`Auto-trading buys tokens named by ${esc(s.name)}. Anyone who controls a source can name a token they own.`)}<p class="muted">Practice mode never trades from messages. This setting is saved in your browser so you can see how arming looks.</p><label style="display:flex;gap:10px;color:var(--ink)"><input type="checkbox" id="ar" style="width:auto;min-height:0;margin-top:3px">I want ${esc(s.name)} to trade within my wallet limits.</label></div>`,actions:[{label:'Stay in preview',cls:'ghost'},{label:'Turn on',cls:'primary',fn:()=>{if(!$('#ar').checked){toast('warn','Confirm first','Tick the box to turn on auto-trading.');return false}s.mode='auto';sv()}}]})}}},
addSrc(){modal({title:'Add a source',body:`<div class="stack"><div><label for="an">Channel or group name</label><input id="an" placeholder="e.g. My alpha channel"></div><div><label for="ap">Preset</label><select id="ap"><option>Contracts only</option><option>New launches</option><option>Large buys</option></select></div>${notice('plain','Starts as preview only','New sources never trade. You decide later, per source.')}</div>`,actions:[{label:'Cancel',cls:'ghost'},{label:'Add source',cls:'primary',fn:()=>{const n=$('#an').value.trim();if(!n){toast('warn','Name the source','Give it a name so you can tell it apart.');return false}S.sources.push({id:'s'+Date.now(),name:n,kind:'Telegram channel',mode:'preview',preset:$('#ap').value,last:'never'});store.set('sources',S.sources);this.drawSrc()}}]})},
drawAct(){const el=$('#sa');if(!el)return;el.innerHTML=sigAct.length?`<div class="tw"><table><thead><tr><th>Token</th><th>Message</th><th>Validation</th><th>Action</th></tr></thead><tbody>${sigAct.map(x=>`<tr><td>${x.sym?`<b>${esc(x.sym)}</b>`:`<span class="mono">${short(x.address)}</span>`}</td><td class="muted">${esc(x.msg)}…<div class="faint" style="font-size:12px">${x.at}</div></td><td>${x.status==='unknown'?'<span class="chip warn">Not found</span>':chipV(x.verdict)}<div class="muted" style="font-size:12px">${esc(x.message)}</div></td><td>${x.token?`<button class="btn sm" data-open="${x.token}">Open in Trade</button>`:'<span class="muted">Ignored</span>'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><b>No detections yet</b>Detected tokens appear here with the check result and the action taken. Nothing is bought from a message.</div>`;
  el.onclick=e=>{const b=e.target.closest('[data-open]');if(b){S.token=b.dataset.open;go('trade')}}}};
/* ---------- Watched real wallets (read-only): balances of any public address ---------- */
const WK='mint.watch.v1';
const getWatch=()=>{try{const a=JSON.parse(localStorage.getItem(WK)||'[]');return Array.isArray(a)?a:[]}catch{return[]}};
const putWatch=a=>{try{localStorage.setItem(WK,JSON.stringify(a))}catch{}};
const wamt=(raw,dec)=>{const n=Number(BigInt(raw))/10**dec;return n>=1000?compact(n):n>=1?n.toFixed(2):n===0?'0':n.toPrecision(3)};
const usdf=v=>v==null?'<span class="muted" title="No market price found">Unknown</span>':'$'+compact(v);
async function watchData(force){S.wv=S.wv||{};const out=[];for(const w of getWatch()){const k=w.chain+':'+w.address,c=S.wv[k];if(c&&!force&&Date.now()-c.at<30000){out.push(c.d);continue}let d;try{d=await api('/api/watch/wallet',w)}catch{d={ok:false,title:'Could not reach the server',why:'The request failed.',fix:'Check that the server is running.'}}S.wv[k]={at:Date.now(),d:{...d,chain:w.chain,address:w.address}};out.push(S.wv[k].d)}return out}
function watchMount(mode){
  if(!S.realInfo?.enabled||$('#ww'))return;const host=document.querySelector('.pagehead');if(!host)return;
  const box=document.createElement('div');box.id='ww';box.className='panel stack';box.style.marginBottom='14px';
  box.innerHTML=`<h2>${mode==='wallets'?'Watch a real wallet':'Real holdings'}</h2><p class="muted">Paste any public address to see its real balances on Ethereum, BNB or Solana. Read-only: no keys, nothing can be traded or moved. Prices come from a third party (DexScreener) and can be wrong or missing.</p>
  <div class="row"><div><label for="wc">Chain</label><select id="wc"><option value="ethereum">Ethereum</option><option value="bnb">BNB</option><option value="solana">Solana</option></select></div><div style="flex:1;min-width:220px"><label for="wa">Address</label><input id="wa" placeholder="0x… or a Solana address" autocomplete="off" spellcheck="false"></div><div style="align-self:end"><button class="btn primary" id="wgo">Watch</button></div></div><div id="wl2" aria-live="polite">${skeleton(1)}</div>`;
  host.insertAdjacentElement('afterend',box);
  const draw=async(force)=>{const el=$('#wl2');if(!el)return;const list=await watchData(force),sig=JSON.stringify(list.map(x=>[x.address,x.at,x.totalUsd]));if(!force&&el.dataset.sig===sig)return;el.dataset.sig=sig;el.innerHTML=watchHtml(list,mode)};
  box.onclick=async e=>{const r=e.target.closest('[data-rm]');if(r){putWatch(getWatch().filter(w=>w.chain+':'+w.address!==r.dataset.rm));draw(true)}};
  $('#wgo').onclick=async()=>{const chain=$('#wc').value,address=$('#wa').value.trim();if(!address)return toast('warn','Enter an address','Paste a public wallet address first.');
    const d=await act('/api/watch/wallet',{chain,address});if(!d||d.ok===false)return;const a=getWatch();if(a.some(w=>w.chain===chain&&w.address.toLowerCase()===d.address.toLowerCase()))return toast('plain','Already watching','This address is already in your list.');
    if(a.length>=10)return toast('warn','Limit reached','You can watch up to 10 addresses.');a.push({chain,address:d.address});putWatch(a);$('#wa').value='';draw(true)};
  draw(true);S.watchDraw=draw}
function watchHtml(list,mode){
  if(!list.length)return `<div class="empty" style="padding:16px"><b>No wallet watched yet</b>Paste an address above. Your list is saved in this browser only.</div>`;
  const row=(w,sym,name,amount,dec,price,usd,contract)=>`<tr><td data-l="Token"><b>${esc(sym)}</b> <span class="faint">${esc(name||'')}</span></td><td data-l="Wallet">${chainChip(w.chain)} ${esc(short(w.address))}</td><td data-l="Held" class="r num">${secret(wamt(amount,dec))}</td><td data-l="Price" class="r num">${price==null?'<span class="muted">–</span>':'$'+(price<0.01?price.toPrecision(3):compact(price))}</td><td data-l="Value" class="r num">${secret(usdf(usd))}</td></tr>`;
  const ok=list.filter(x=>x.ok!==false),bad=list.filter(x=>x.ok===false);
  const tot=ok.reduce((a,w)=>a+(w.totalUsd||0),0);
  let body=ok.map(w=>row(w,w.native.sym,'native',w.native.amount,w.native.decimals,w.native.usd!=null&&Number(w.native.amount)>0?w.native.usd/(Number(BigInt(w.native.amount))/10**w.native.decimals):null,w.native.usd,'')+w.tokens.map(t=>row(w,t.sym,t.name,t.amount,t.decimals,t.price,t.usd,t.contract)).join('')).join('');
  const head=`<div class="row sb" style="margin:6px 0"><b>${ok.length} wallet${ok.length===1?'':'s'} watched</b><span>Total of priced holdings: <b class="num">${secret('$'+compact(tot))}</b></span></div>`;
  const per=ok.map(w=>`<div class="row sb faint" style="font-size:12.5px;margin-top:4px"><span>${chainChip(w.chain)} <span title="${esc(w.address)}">${esc(short(w.address))}</span> · ${w.tokens.length} holding${w.tokens.length===1?'':'s'}${w.totalUsd!=null?' · $'+compact(w.totalUsd):''}</span><button class="btn ghost" data-rm="${esc(w.chain+':'+w.address)}">Remove</button></div>`).join('');
  const notes=[...new Set(ok.flatMap(w=>w.notes||[]))].map(n=>`<p class="muted" style="margin:3px 0;font-size:12.5px">${esc(n)}</p>`).join('');
  const errs=bad.map(w=>notice('error',esc(w.title||'Could not read this address'),esc((w.why||'')+' '+(w.fix||''))+` <button class="btn ghost" data-rm="${esc(w.chain+':'+w.address)}">Remove</button>`)).join('');
  return head+`<div class="tw"><table class="tbl-cards"><thead><tr><th>Token</th><th>Wallet</th><th class="r">Held</th><th class="r">Price</th><th class="r">Value</th></tr></thead><tbody>${body}</tbody></table></div>`+per+notes+errs+(mode==='portfolio'?`<p class="muted" style="font-size:12.5px">Cost and profit are not shown: for a wallet you only watch, what it paid is not known.</p>`:'')}
/* ---------- Tracked real wallets (Copy trade, track only): recent real trades of any public address ---------- */
const TKK='mint.track.v1';
const getTrack=()=>{try{const a=JSON.parse(localStorage.getItem(TKK)||'[]');return Array.isArray(a)?a:[]}catch{return[]}};
const putTrack=a=>{try{localStorage.setItem(TKK,JSON.stringify(a))}catch{}};
async function trackData(force){S.wt=S.wt||{};const out=[],tw=getTrack();let pulse={};if(!force&&tw.some(w=>S.wt[w.chain+':'+w.address]?.d?.push)){try{const r=await api('/api/watch/pulse',{items:tw});for(const i of r.items||[])pulse[i.chain+':'+i.address]=i}catch{}}
  for(const w of tw){const k=w.chain+':'+w.address,c=S.wt[k],pl=pulse[k];if(c&&!force&&Date.now()-c.at<60000&&!(pl&&pl.activityAt>c.at)){if(pl)c.d.pushLive=pl.live;out.push(c.d);continue}let d;try{d=await api('/api/watch/trades',w)}catch{d={ok:false,title:'Could not reach the server',why:'The request failed.',fix:'Check that the server is running.'}}S.wt[k]={at:Date.now(),d:{...d,chain:w.chain,address:w.address,fetched:Date.now()}};out.push(S.wt[k].d)}return out}
function trackHtml(list){
  if(!list.length)return `<div class="empty" style="padding:16px"><b>No wallet tracked yet</b>Paste the address of a trader you want to study. Your list is saved in this browser only.</div>`;
  const when=ts=>{if(!ts)return '–';const ms=ts<1e12?ts*1000:ts;return ago(Math.max(0,Math.round((Date.now()-ms)/60000)))+' ago'};
  const amt=(raw,dec)=>dec==null?'':wamt(raw,dec);
  return list.map(w=>{if(w.ok===false)return notice('error',esc(w.title||'Could not read this wallet'),esc((w.why||'')+' '+(w.fix||''))+` <button class="btn ghost" data-trm="${esc(w.chain+':'+w.address)}">Remove</button>`);
    const sw=w.items.filter(i=>i.kind==='swap'),buys=sw.filter(i=>i.side==='buy').length;
    return `<div class="stack" style="margin-top:10px"><div class="row sb"><span>${chainChip(w.chain)} <b title="${esc(w.address)}">${esc(short(w.address))}</b> ${w.push&&w.pushLive!==false?'<span class="chip ok" title="New activity from this wallet is pushed to the server within seconds, then this list refreshes.">Live</span>':''} <span class="faint">· ${sw.length} swap${sw.length===1?'':'s'} (${buys} buy${buys===1?'':'s'}, ${sw.length-buys} sell${sw.length-buys===1?'':'s'}) among the ${w.items.length} listed</span></span><button class="btn ghost" data-trm="${esc(w.chain+':'+w.address)}">Remove</button></div>
    ${w.items.length?`<div class="tw"><table class="tbl-cards"><thead><tr><th>When</th><th>Action</th><th>Token</th><th class="r">Size</th><th>What your rules would do</th></tr></thead><tbody>${w.items.map(i=>`<tr><td data-l="When">${when(i.ts)}</td><td data-l="Action">${i.kind==='swap'?`<span class="chip ${i.side==='buy'?'ok':'bad'}">${i.side==='buy'?'Bought':'Sold'}</span>`:'<span class="chip">Transfer</span>'}</td><td data-l="Token"><b>${esc(i.sym||short(i.token))}</b>${i.name?` <span class="faint">${esc(i.name)}</span>`:''}</td><td data-l="Size" class="r num">${i.kind==='swap'?`${wamt(i.quoteAmount,i.quoteDecimals)} ${esc(i.quoteSym)}${amt(i.tokenAmount,i.tokenDecimals)?'<div class="faint" style="font-size:11.5px">'+amt(i.tokenAmount,i.tokenDecimals)+' tokens</div>':''}`:'–'}</td><td data-l="Rules" style="font-size:12.5px">${esc(i.decision)}</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted">No recent token trades found for this wallet.</p>`}
    ${(w.notes||[]).map(n=>`<p class="muted" style="margin:2px 0;font-size:12.5px">${esc(n)}</p>`).join('')}</div>`}).join('')}
function trackMount(){
  if(!S.realInfo?.enabled||$('#tw'))return;const host=document.querySelector('.pagehead');if(!host)return;
  const box=document.createElement('div');box.id='tw';box.className='panel stack';box.style.marginBottom='14px';
  box.innerHTML=`<h2>Track a real wallet</h2><p class="muted">Paste any public address to see its real recent swaps and what your copy rules would do with each one. Track only: nothing is bought or sold, and no key is needed. Swaps are read from the wallet's own balance changes.</p>
  <div class="row"><div><label for="tc">Chain</label><select id="tc"><option value="solana">Solana</option><option value="ethereum">Ethereum</option><option value="bnb">BNB</option></select></div><div style="flex:1;min-width:220px"><label for="ta">Address</label><input id="ta" placeholder="Wallet address" autocomplete="off" spellcheck="false"></div><div style="align-self:end"><button class="btn primary" id="tgo">Track</button></div></div><div id="tl" aria-live="polite">${skeleton(1)}</div>`;
  host.insertAdjacentElement('afterend',box);
  const draw=async force=>{const el=$('#tl');if(!el)return;const list=await trackData(force),sig=JSON.stringify(list.map(x=>[x.address,x.fetched]));if(!force&&el.dataset.sig===sig)return;el.dataset.sig=sig;el.innerHTML=trackHtml(list)};
  box.onclick=e=>{const r=e.target.closest('[data-trm]');if(r){putTrack(getTrack().filter(w=>w.chain+':'+w.address!==r.dataset.trm));draw(true)}};
  $('#tgo').onclick=async()=>{const chain=$('#tc').value,address=$('#ta').value.trim();if(!address)return toast('warn','Enter an address','Paste a public wallet address first.');
    $('#tgo').disabled=true;const d=await act('/api/watch/trades',{chain,address});$('#tgo').disabled=false;if(!d||d.ok===false)return;const a=getTrack();
    if(a.some(w=>w.chain===chain&&w.address.toLowerCase()===d.address.toLowerCase()))return toast('plain','Already tracking','This address is already in your list.');if(a.length>=5)return toast('warn','Limit reached','You can track up to 5 wallets.');
    a.push({chain,address:d.address});putTrack(a);$('#ta').value='';draw(true)};
  draw(true);S.trackDraw=draw}
const chipV=v=>({'no-flags':'<span class="chip ok">Tests passed</span>',warn:'<span class="chip warn">Caution</span>',quarantined:'<span class="chip warn">Unusual behaviour</span>',blocked:'<span class="chip bad">Do not trade</span>'}[v]||'<span class="chip">Unknown</span>');

/* ---------- Wallets ---------- */
const FLOWS={fund:['Fund a wallet','Add funds to a wallet. Practice and fork wallets are pre-funded; on a live network you would send from an exchange or another wallet to the address shown.'],distribute:['Distribute','Split a balance from one wallet across several.'],consolidate:['Consolidate','Move balances from several wallets into one.'],send:['Send','Send to an address you have approved in wallet settings.'],bridge:['Bridge','Move assets to another chain. Progress is tracked in four stages.']};
function bridgeStages(fail){const st=['Source transaction','Bridge processing','Destination received','Optional swap'];return `<ol class="steps" style="flex-direction:column;gap:10px">${st.map((s,i)=>`<li class="${i<3?'done':fail&&i===3?'':'on'}"><b>${i<3?'✓':fail&&i===3?'✕':'4'}</b><span>${s}${fail&&i===3?' <span class="chip bad">Failed</span>':''}</span></li>`).join('')}</ol>`}
V.wallets={title:'Wallets',needsData:true,
html(){return practiceNote()+head('Wallets','Balances by wallet, asset and chain. Each wallet has its own limits and can stop automation at any time.',`<button class="btn" id="agg" aria-pressed="false">Show totals</button>`)+
  `<div class="row" style="margin-bottom:14px">${Object.entries(FLOWS).map(([k,v])=>`<button class="btn ${k==='fund'?'primary':''}" data-flow="${k}">${v[0]}</button>`).join('')}</div><div class="stack"><div class="panel flush"><div class="tw" id="wb"></div></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr))" id="wl"></div>
  ${isLive()?'':`<div class="panel stack"><h2>Bridge status example ${sampleTag}</h2><p class="muted">If the final swap on the destination chain fails, your assets are not lost. This is how that looks.</p>${bridgeStages(true)}${notice('warn','Swap failed, assets arrived',`<div>Your 500 USDC arrived on the destination chain in this wallet, unswapped.</div><div><b style="display:inline">Recovery:</b> retry the swap with a higher slippage limit, or keep the USDC.</div>`)}<div class="row"><button class="btn sm" disabled>Retry swap</button><button class="btn sm" disabled>Keep USDC</button></div></div>`}</div>`},
mount(){watchMount('wallets');this.agg=false;$('#agg').onclick=e=>{this.agg=!this.agg;e.target.setAttribute('aria-pressed',this.agg);e.target.textContent=this.agg?'Show by wallet':'Show totals';this.tick(true)};
  $('#view').addEventListener('click',e=>{const f=e.target.closest('[data-flow]');if(f)this.flow(f.dataset.flow)});this.tick(true);if(S.nav?.flow)this.flow(S.nav.flow)},
tick(force){if(!$('#wb'))return;const ws=S.ov.wallets;const rows=[];ws.forEach(w=>{rows.push([w.name+(w.address?` · ${short(w.address)}`:''),QSYM(),w.native,'native']);w.tokens.forEach(k=>rows.push([w.name+(w.address?` · ${short(w.address)}`:''),k.sym,k.bal,k.token]))});
  let body=rows.map(r=>`<tr><td data-l="Wallet">${esc(r[0])}</td><td data-l="Asset">${esc(r[1])}</td><td data-l="Chain">${chainChip('practice')}</td><td data-l="Balance" class="r num">${secret(fa(r[2],r[3],{bare:true}))}</td></tr>`).join('');
  if(this.agg){const t={};rows.forEach(r=>{t[r[3]]=t[r[3]]||{sym:r[1],v:0n};t[r[3]].v+=BigInt(r[2])});body=Object.entries(t).map(([id,x])=>`<tr><td data-l="Wallet">All wallets</td><td data-l="Asset">${esc(x.sym)}</td><td data-l="Chain">${chainChip('practice')}</td><td data-l="Balance" class="r num">${secret(fa(x.v,id,{bare:true}))}</td></tr>`).join('')}
  $('#wb').innerHTML=`<table class="tbl-cards"><thead><tr><th>Wallet</th><th>Asset</th><th>Chain</th><th class="r">Balance</th></tr></thead><tbody>${body}</tbody></table>`;
  const wl=$('#wl');if(wl.contains(document.activeElement)&&!force)return;wl.innerHTML=ws.map(w=>`<div class="panel stack"><h2>${esc(w.name)}</h2><div class="kv"><span>Limit per trade</span><b class="num">${fa(w.policy.maxPerTx,'native')}</b></div><div class="kv"><span>Daily limit</span><b class="num">${fa(w.policy.daily,'native')}</b></div><div class="kv"><span>Spent today</span><b class="num">${secret(fa(w.spentToday,'native'))}</b></div>
  ${isLive()?'<p class="hint faint">The per-wallet automation switch is not available on the local fork. Use Pause new automated entries at the top to stop automated buys.</p>':`<label style="display:flex;gap:10px;align-items:center;color:var(--ink);margin:0"><input type="checkbox" data-w="${w.id}" ${w.policy.automationPaused?'':'checked'} style="width:auto;min-height:0"><span>Allow automation <span class="muted">(orders, copy, sniper)</span></span></label><p class="hint faint">${w.policy.automationPaused?'Automation is off: only manual trades can sign for this wallet.':'Automation can sign within the limits above.'}</p>`}</div>`).join('');
  wl.onchange=async e=>{const i=e.target.closest('[data-w]');if(i)await api('/api/wallets/automation',{id:i.dataset.w,paused:!i.checked})}},
flow(k){const [t,d]=FLOWS[k];modal({title:t,body:`<div class="stack"><p class="muted">${d}</p><div><label for="ff">From</label><select id="ff">${wOpts('w1')}</select></div>${k==='bridge'?`<div><label for="fc">To chain</label><select id="fc">${Object.entries(CHAINS).filter(([x])=>x!=='practice').map(([x,c])=>`<option>${c.name}</option>`).join('')}</select></div>`:`<div><label for="ft2">To</label><select id="ft2">${wOpts('w2')}</select></div>`}<div><label for="fa2">Amount (${QSYM()})</label><input id="fa2" inputmode="numeric" placeholder="0"></div>${k==='bridge'?bridgeStages(false):''}${notice('warn',`Moving funds is off in ${MODE()}`,isLive()?'You can fill this in to see the flow, but nothing is sent. Wallets on the fork are funded with fake ETH when the server starts.':'You can fill this in to see the flow, but nothing is sent. Funds only move on a live network with your own signing approval.')}</div>`,actions:[{label:'Close',cls:'ghost'},{label:t,cls:'primary',disabled:true}]})}};

