V.portfolio={title:'Portfolio',needsData:true,
html(){return practiceNote()+head('Portfolio','What you hold, what it cost and how it is doing. Profit is shown only where the cost is known.')+`<div class="stack"><div class="panel flush"><div class="ph"><h2>Holdings</h2></div><div class="tw" id="po">${skeleton(2)}</div></div><div class="panel flush"><div class="ph"><h2>Recent trades</h2></div><div class="tw" id="ph"></div></div></div>`},
mount(){watchMount('portfolio');this.tick()},
async tick(){S.watchDraw&&S.watchDraw(false);const po=$('#po');if(!po)return;let p;try{p=await api('/api/portfolio')}catch{po.innerHTML=failBox('your portfolio');return}
  const u=x=>x==null?'<span class="muted" title="Not known, for example for tokens received by transfer">Unknown</span>':secret(`<b class="num ${BigInt(x)>=0n?'up':'dn'}">${BigInt(x)>=0n?'+':''}${fmt(x)}</b>`);
  po.innerHTML=p.positions.length?`<table class="tbl-cards"><thead><tr><th>Token</th><th>Chain</th><th class="r">Held</th><th class="r">Average cost</th><th class="r">Open P&amp;L</th><th class="r">Closed P&amp;L</th></tr></thead><tbody>${p.positions.map(x=>`<tr><td data-l="Token"><b>${esc(x.sym)}</b></td><td data-l="Chain">${chainChip('practice')}</td><td data-l="Held" class="r num">${secret(fmt(x.balance))}</td><td data-l="Avg cost" class="r num">${x.avgCost?(Number(x.avgCost.num)/Number(x.avgCost.den)).toFixed(4)+' SIM':'Unknown'}</td><td data-l="Open P&L" class="r">${u(x.unrealizedPnl)}</td><td data-l="Closed P&L" class="r">${u(x.realizedPnl)}</td></tr>`).join('')}</tbody></table>`:`<div class="empty"><b>No holdings yet</b>Trades you make, and trades from your rules, build your portfolio.<br><button class="btn primary" onclick="go('trade')">Open Trade</button></div>`;
  $('#ph').innerHTML=p.history.length?`<table class="tbl-cards"><thead><tr><th>Trade</th><th class="r">Tokens</th><th class="r">SIM</th></tr></thead><tbody>${p.history.map(h=>`<tr><td data-l="Trade"><span class="chip ${h.side==='buy'?'ok':'bad'}">${h.side==='buy'?'Bought':'Sold'}</span> ${esc(h.sym)}</td><td data-l="Tokens" class="r num">${secret(fmt(h.tokenQty))}</td><td data-l="SIM" class="r num">${secret(fmt(h.quoteAmount))}</td></tr>`).join('')}</tbody></table>`:`<div class="empty"><b>No trades yet</b>Confirmed fills appear here.</div>`}};

