  const f=lsForm('whale',{min:'50000',types:['buy','sell'],chain:'all',watch:''}).get(),min=Number(f.min)||0,watch=String(f.watch||'').split(/[\s,]+/).filter(Boolean).map(x=>x.toLowerCase());let r;
  try{r=await api('/api/whales?min='+(watch.length?Math.min(min,100):min)+'&chain='+encodeURIComponent(f.chain))}catch{el.innerHTML=notice('error','Could not load the feed','The terminal did not answer. Retrying automatically.');return}
